/** Original, offline vector artwork. Each part remains an editable Fabric Path. */
export interface GraphicPath {
  path:string; fill:string; stroke?:string; strokeWidth?:number;
  strokeLineCap?:'round'|'butt'|'square'; strokeLineJoin?:'round'|'miter'|'bevel';
  opacity?:number; name?:string;
}
export interface OriginalGraphic {
  id:string; name:string; category:string; tags:string[];
  width:number; height:number; parts:GraphicPath[]; palette:string[];
}
export const GRAPHICS_PROVENANCE={author:'Visro contributors',license:'AGPL-3.0-only',source:'Independently authored SVG path artwork',networkRequired:false,animation:'static'} as const;
const INK='#30333b',PURPLE='#7653b7',LILAC='#d7c8ee',GREEN='#63866a',MINT='#c7dcc8',PEACH='#dc9d7b',GOLD='#e5b85c',PINK='#dca3b8',BLUE='#7098bb',PAPER='#fff6e4';
const rounded=(n:number)=>Math.round(n*100)/100;
const path=(d:string,fill='none',stroke:string|undefined=INK,strokeWidth=6):GraphicPath=>({path:d,fill,stroke,strokeWidth,strokeLineCap:'round',strokeLineJoin:'round'});
const solid=(d:string,fill=PURPLE)=>path(d,fill,undefined,0);
const line=(d:string,stroke=INK,strokeWidth=6)=>path(d,'none',stroke,strokeWidth);
const poly=(points:number[][])=>points.map(([x,y],i)=>`${i?'L':'M'}${rounded(x)} ${rounded(y)}`).join(' ')+' Z';
const circle=(x:number,y:number,r:number,fill='none',stroke:string|undefined=INK,sw=6)=>path(`M${x-r} ${y} a${r} ${r} 0 1 0 ${r*2} 0 a${r} ${r} 0 1 0 ${-r*2} 0 Z`,fill,stroke,sw);
const ellipse=(x:number,y:number,rx:number,ry:number,fill='none',stroke:string|undefined=INK,sw=6)=>path(`M${x-rx} ${y} a${rx} ${ry} 0 1 0 ${rx*2} 0 a${rx} ${ry} 0 1 0 ${-rx*2} 0 Z`,fill,stroke,sw);
const rect=(x:number,y:number,w:number,h:number,r=0,fill='none',stroke:string|undefined=INK,sw=6)=>path(r?`M${x+r} ${y} H${x+w-r} Q${x+w} ${y} ${x+w} ${y+r} V${y+h-r} Q${x+w} ${y+h} ${x+w-r} ${y+h} H${x+r} Q${x} ${y+h} ${x} ${y+h-r} V${y+r} Q${x} ${y} ${x+r} ${y} Z`:`M${x} ${y} H${x+w} V${y+h} H${x} Z`,fill,stroke,sw);
const star=(n:number,r:number,inner:number,cx=100,cy=100,angle=-Math.PI/2)=>poly(Array.from({length:n*2},(_,i)=>{const a=angle+i*Math.PI/n,s=i%2?inner:r;return[cx+Math.cos(a)*s,cy+Math.sin(a)*s];}));
const ring=(n:number,r:number,cx=100,cy=100)=>poly(Array.from({length:n},(_,i)=>[cx+Math.cos(-Math.PI/2+i*2*Math.PI/n)*r,cy+Math.sin(-Math.PI/2+i*2*Math.PI/n)*r]));
const leaf=(x:number,y:number,w:number,h:number,fill=GREEN)=>solid(`M${x} ${y+h} C${x-w*.2} ${y+h*.35} ${x+w*.3} ${y} ${x+w} ${y} C${x+w*1.15} ${y+h*.6} ${x+w*.65} ${y+h*1.15} ${x} ${y+h} Z`,fill);
const rays=(count:number,inner:number,outer:number,cx=100,cy=100,start=0)=>line(Array.from({length:count},(_,i)=>{const a=start+i*Math.PI*2/count;return`M${rounded(cx+Math.cos(a)*inner)} ${rounded(cy+Math.sin(a)*inner)} L${rounded(cx+Math.cos(a)*outer)} ${rounded(cy+Math.sin(a)*outer)}`;}).join(' '));
const library:OriginalGraphic[]=[];
function add(id:string,name:string,category:string,tags:string,parts:GraphicPath[],width=200,height=200){
  library.push({id:`graphic-${id}`,name,category,tags:tags.split(' '),width,height,parts:parts.map((p,i)=>({...p,name:p.name||`${name} / part ${i+1}`})),palette:[...new Set(parts.flatMap(p=>[p.fill,p.stroke].filter((color):color is string=>!!color&&color!=='none')))]});
}

