export const GRAPHICS:OriginalGraphic[]=library;
export function getGraphic(id:string):OriginalGraphic|undefined{return GRAPHICS.find(graphic=>graphic.id===id);}
export function searchGraphics(query='',category='All'):OriginalGraphic[]{
  const terms=query.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);
  return GRAPHICS.filter(graphic=>(category==='All'||graphic.category===category)&&terms.every(term=>`${graphic.name} ${graphic.category} ${graphic.tags.join(' ')}`.toLocaleLowerCase().includes(term)));
}
const xml=(value:string)=>value.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]!));
export function graphicToSVG(graphic:OriginalGraphic):string{
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${graphic.width}" height="${graphic.height}" viewBox="0 0 ${graphic.width} ${graphic.height}"><title>${xml(graphic.name)}</title>${graphic.parts.map(part=>`<path d="${xml(part.path)}" fill="${xml(part.fill)}"${part.stroke?` stroke="${xml(part.stroke)}"`:''} stroke-width="${part.strokeWidth??0}" stroke-linecap="${part.strokeLineCap??'round'}" stroke-linejoin="${part.strokeLineJoin??'round'}"${part.opacity!==undefined?` opacity="${part.opacity}"`:''}/>`).join('')}</svg>`;
}

